/* generated child CSS: 07-comparison/comparison.three-col-with-mobile-cards/block.css */
/* lab-ui block · comparison.three-col-with-mobile-cards
   Depends: 00-tokens/tokens.css. Light theme. */

.compare {
  --compare-secondary-columns: 5;
  background: var(--color-bg);
  color: var(--color-text);
  font-family: var(--font-family);
}
.compare[data-columns="2"] { --compare-secondary-columns: 1; }
.compare[data-columns="3"] { --compare-secondary-columns: 2; }
.compare[data-columns="4"] { --compare-secondary-columns: 3; }
.compare[data-columns="5"] { --compare-secondary-columns: 4; }
.compare[data-columns="6"] { --compare-secondary-columns: 5; }
.compare .container {
  max-width: calc(var(--container-width) + var(--container-padding-x) * 2);
  margin-inline: auto;
  padding-inline: var(--container-padding-x);
}

.compare-top {
  max-width: 54rem;
  margin: 0 auto clamp(2rem, 4vw, 3.25rem);
  text-align: center;
}
.compare-top .eyebrow {
  font-family: var(--font-mono);
  font-size: var(--type-eyebrow-size);
  text-transform: uppercase;
  letter-spacing: var(--type-eyebrow-tracking);
  background: var(--cta-secondary-fill, linear-gradient(90deg, #56422D 0%, #494938 100%));
  background-clip: text;
  -webkit-background-clip: text;
  color: transparent;
  margin: 0 0 14px;
}
.compare-title {
  margin: 0 0 14px;
  font-weight: var(--type-h2-weight);
  font-size: var(--type-h2-size);
  line-height: var(--type-h2-leading);
  letter-spacing: var(--type-h2-tracking);
  color: var(--color-heading);
}
.compare-lede {
  margin: 0;
  font-size: var(--type-lead-size);
  line-height: var(--type-lead-leading);
  color: var(--color-text);
}

.compare-grid {
  position: relative;
  overflow: hidden;
  border: 1px solid rgba(146, 170, 205, 0.26);
  border-radius: 22px;
  background:
    radial-gradient(circle at 52% 8%, rgba(255, 255, 255, 0.92), rgba(255, 255, 255, 0) 34%),
    linear-gradient(180deg, var(--color-white) 0%, #fbfcfe 62%, #f6f8fb 100%);
  box-shadow: 0 20px 60px rgba(17, 24, 39, 0.06);
}
/* Uniform soft cyan-tint border stroke. Previous 135deg cyan→white→gray
   read as a directional accent — too loud. The whole table now sits in a
   single calm cyan halo with a slight top-to-bottom falloff. */
.compare-grid::before {
  content: "";
  position: absolute;
  inset: 0;
  padding: 1px;
  border-radius: inherit;
  pointer-events: none;
  z-index: 4;
  background: linear-gradient(
    180deg,
    rgba(107, 234, 249, 0.40) 0%,
    rgba(107, 234, 249, 0.18) 100%
  );
  -webkit-mask:
    linear-gradient(#000 0 0) content-box,
    linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
          mask-composite: exclude;
}

.compare-row {
  position: relative;
  display: grid;
  grid-template-columns: minmax(210px, 1.62fr) minmax(150px, 1.15fr) repeat(var(--compare-secondary-columns), minmax(140px, 1fr));
  min-height: 72px;
  z-index: 1;
}

.compare[data-columns="2"] [data-compare-col="3"],
.compare[data-columns="2"] [data-compare-col="4"],
.compare[data-columns="2"] [data-compare-col="5"],
.compare[data-columns="2"] [data-compare-col="6"],
.compare[data-columns="3"] [data-compare-col="4"],
.compare[data-columns="3"] [data-compare-col="5"],
.compare[data-columns="3"] [data-compare-col="6"],
.compare[data-columns="4"] [data-compare-col="5"],
.compare[data-columns="4"] [data-compare-col="6"],
.compare[data-columns="5"] [data-compare-col="6"] {
  display: none;
}

.compare-cell {
  min-width: 0;
  padding: 16px 18px;
  display: flex;
  align-items: center;
  color: var(--color-heading);
  font-size: clamp(0.875rem, 0.74vw, 1rem);
  line-height: 1.34;
}
.compare-cell--head {
  align-items: flex-start;
  padding-top: 28px;
  color: var(--color-heading);
  font-weight: 500;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.compare-cell--empty {
  visibility: hidden;
}

.compare-brand {
  display: block;
  min-width: 0;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  align-items: baseline;
  color: var(--color-heading);
  font-size: clamp(0.9375rem, 0.86vw, 1.0625rem);
  letter-spacing: -0.02em;
}
.compare-brand strong {
  font-weight: 800;
}

.compare-cell--capability {
  padding-left: clamp(1.5rem, 2.4vw, 2.75rem);
  font-size: clamp(1rem, 1.03vw, 1.1875rem);
  font-weight: 500;
  letter-spacing: -0.02em;
  color: var(--color-heading);
}
.compare-capability {
  overflow: hidden;
  text-overflow: ellipsis;
}

/* the platform column — one floating white card that spans the whole
   column. Body cells render the vertical edges of the card via inset
   strokes; head ::before and last-row ::after close the rounded top
   and bottom corners and add the outer drop shadow. Solid white
   (was rgba 0.72) so it stays opaque over the grid's gray-fade bottom,
   no need for backdrop-filter blur. Cyan stroke alpha lowered from
   0.72 → 0.38 so the column reads as outlined, not bracketed. */
.compare-cell--sw {
  position: relative;
  z-index: 2;
  margin-inline: 0.28rem;
  background: var(--color-white);
  border-left: 0;
  border-right: 0;
  box-shadow:
    inset 1px 0 rgba(107, 234, 249, 0.38),
    inset -1px 0 rgba(107, 234, 249, 0.38);
}
.compare-cell--sw > * {
  position: relative;
  z-index: 1;
}
.compare-row--head .compare-cell--sw {
  margin-top: 0;
  padding-top: 28px;
  border-top: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
}
.compare-row--head .compare-cell--sw::before {
  content: "";
  position: absolute;
  inset: 12px 0 0;
  border-radius: 14px 14px 0 0;
  pointer-events: none;
  background: var(--color-white);
  box-shadow:
    0 -10px 24px -12px rgba(17, 24, 39, 0.12),
    inset 1px 0 rgba(107, 234, 249, 0.38),
    inset -1px 0 rgba(107, 234, 249, 0.38),
    inset 0 1px rgba(107, 234, 249, 0.45);
}
/* Last-row SW cell: symmetric to head — the cell itself is transparent
   (no stroke leakage past the rounded bottom). All visible card geometry
   for the bottom edge is painted by ::after: white fill, rounded bottom
   corners, cyan inset edges (left/right/bottom), and the outer drop
   shadow. The 12 px below ::after is grid background, giving the card
   visible breathing room and clean rounded corners. */
.compare-body .compare-row:last-child .compare-cell--sw {
  margin-bottom: 0;
  border-bottom: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
}
.compare-body .compare-row:last-child .compare-cell--sw::after {
  content: "";
  position: absolute;
  inset: 0 0 12px;
  border-radius: 0 0 14px 14px;
  pointer-events: none;
  background: var(--color-white);
  box-shadow:
    0 18px 28px -14px rgba(17, 24, 39, 0.16),
    inset 1px 0 rgba(107, 234, 249, 0.38),
    inset -1px 0 rgba(107, 234, 249, 0.38),
    inset 0 -1px rgba(107, 234, 249, 0.45);
}

.compare-status {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
  white-space: nowrap;
}
.compare-status > span:last-child {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}
.compare-icon {
  width: 19px;
  height: 19px;
  flex: 0 0 19px;
  position: relative;
  border-radius: 999px;
}
.compare-status--check .compare-icon,
.compare-status--yes .compare-icon {
  background: var(--color-status-yes, #76D98F);
}
.compare-status--neutral .compare-icon,
.compare-status--partial .compare-icon {
  background: var(--color-status-partial, #D7D9DC);
}
.compare-status--cross .compare-icon,
.compare-status--no .compare-icon {
  background: var(--color-status-no, #FF6B6B);
}
.compare-status--check .compare-icon::before,
.compare-status--yes .compare-icon::before,
.compare-status--neutral .compare-icon::before,
.compare-status--partial .compare-icon::before {
  content: "";
  position: absolute;
  left: 5px;
  top: 8px;
  width: 8px;
  height: 4px;
  border-left: 2px solid #F9F9F9;
  border-bottom: 2px solid #F9F9F9;
  border-radius: 1px;
  transform: rotate(-45deg);
}
.compare-status--none .compare-icon {
  display: none;
}
.compare-status--cross .compare-icon::before,
.compare-status--cross .compare-icon::after,
.compare-status--no .compare-icon::before,
.compare-status--no .compare-icon::after {
  content: "";
  position: absolute;
  left: 5px;
  top: 8.5px;
  width: 9px;
  height: 2px;
  border-radius: 999px;
  background: #F9F9F9;
}
.compare-status--cross .compare-icon::before,
.compare-status--no .compare-icon::before {
  transform: rotate(45deg);
}
.compare-status--cross .compare-icon::after,
.compare-status--no .compare-icon::after {
  transform: rotate(-45deg);
}
.compare-status > span:last-child:empty {
  display: none;
}
.compare-mobile-label {
  display: none;
}
.compare-toggle {
  display: none;
}

@media (max-width: 1180px) {
  .compare-row {
    grid-template-columns: minmax(172px, 1.5fr) minmax(118px, 1.05fr) repeat(var(--compare-secondary-columns), minmax(104px, 1fr));
    min-height: 66px;
  }
  .compare-cell {
    padding-inline: 12px;
    font-size: clamp(0.78rem, 1.08vw, 0.92rem);
  }
  .compare-cell--head {
    font-size: clamp(0.76rem, 1.02vw, 0.88rem);
    white-space: nowrap;
  }
  .compare-cell--capability {
    padding-left: clamp(1rem, 1.7vw, 1.5rem);
    font-size: clamp(0.9rem, 1.28vw, 1.04rem);
  }
  .compare-status {
    gap: 8px;
  }
  .compare-status > span:last-child {
    max-width: 100%;
  }
  .compare-row--head .compare-cell--sw {
    margin-top: 0;
  }
  .compare-body .compare-row:last-child .compare-cell--sw {
    margin-bottom: 14px;
  }
}

@media (max-width: 860px) {
  .compare-top {
    text-align: left;
    margin-bottom: 1.5rem;
  }
  .compare-grid {
    display: flex;
    flex-direction: column;
    gap: 14px;
    overflow: visible;
    border: 0;
    border-radius: 0;
    background: transparent;
    box-shadow: none;
  }
  .compare-grid::before,
  .compare-head {
    display: none;
  }
  .compare-body {
    display: flex;
    flex-direction: column;
    gap: 14px;
  }
  .compare-row {
    min-width: 0;
    min-height: 0;
    grid-template-columns: 1fr;
    overflow: hidden;
    border: 1px solid rgba(146, 170, 205, 0.32);
    border-radius: var(--radius-card-sm);
    background: var(--color-white);
    box-shadow: 0 16px 42px rgba(17, 24, 39, 0.06);
  }
  .compare-cell {
    justify-content: space-between;
    gap: 18px;
    padding: 12px 16px;
    border-top: 1px solid rgba(17, 24, 39, 0.06);
    font-size: 0.9375rem;
  }
  .compare-cell:first-child {
    border-top: 0;
  }
  .compare-cell--capability {
    padding: 16px;
    background: #f7fafc;
    font-size: 1.05rem;
  }
  .compare-cell--sw {
    margin: 0;
    border: 0;
    border-top: 1px solid rgba(17, 24, 39, 0.06);
    border-radius: 0;
    box-shadow: inset 3px 0 0 rgba(86, 66, 45, 0.62);
    background: rgba(244, 250, 255, 0.8);
  }
  .compare-body .compare-row:last-child .compare-cell--sw {
    margin-bottom: 0;
    border-bottom: 0;
    border-radius: 0;
  }
  .compare-row:not(.is-expanded) .compare-cell:not(.compare-cell--capability):not(.compare-cell--sw) {
    display: none;
  }
  .compare-toggle {
    width: 100%;
    min-height: 42px;
    padding: 0 16px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    border: 0;
    border-top: 1px solid rgba(17, 24, 39, 0.06);
    background: var(--color-white);
    color: var(--color-gray-blue);
    font: inherit;
    font-size: 0.75rem;
    font-weight: 800;
    line-height: 1;
    text-align: left;
    text-transform: uppercase;
    cursor: pointer;
  }
  .compare-toggle-close {
    display: none;
  }
  .compare-toggle-icon {
    width: 18px;
    height: 18px;
    flex: 0 0 18px;
    position: relative;
    border-radius: 999px;
    background: rgba(86, 66, 45, 0.12);
  }
  .compare-toggle-icon::before,
  .compare-toggle-icon::after {
    content: "";
    position: absolute;
    inset: 50% auto auto 50%;
    width: 9px;
    height: 2px;
    border-radius: 999px;
    background: rgba(86, 66, 45, 0.92);
    transform: translate(-50%, -50%);
  }
  .compare-toggle-icon::after {
    transform: translate(-50%, -50%) rotate(90deg);
  }
  .compare-row.is-expanded .compare-toggle-open,
  .compare-row.is-expanded .compare-toggle-icon::after {
    display: none;
  }
  .compare-row.is-expanded .compare-toggle-close {
    display: inline;
  }
  .compare-mobile-label {
    display: inline;
    flex: 0 1 auto;
    max-width: 46%;
    color: var(--color-gray-blue);
    font-size: 0.75rem;
    font-weight: 700;
    line-height: 1.2;
    text-transform: uppercase;
  }
  .compare-status {
    flex-direction: row-reverse;
    justify-content: flex-end;
    text-align: right;
    white-space: normal;
  }
  .compare-status > span:last-child {
    overflow: visible;
    text-overflow: clip;
  }
}

